INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Wirtschaftliche Aspekte > Auswahlkriterien IT-Produkte > Umweltschutz & Green IT
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen Umweltschutz und Green IT bei der Auswahl von IT-Produkten immer berücksichtigt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Unternehmenszielen und Vorschriften"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Energieeffizienz von IT-Produkten den Umweltschutz fördern?', 2, '[{"text": "Ja", "correct": true, "because": "Reduziert Stromverbrauch und CO₂-Ausstoß"}, {"text": "Nein", "correct": false, "because": "Effizienz ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Green IT nur auf die Hardware von IT-Produkten beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Umfasst auch Software und Prozesse"}, {"text": "Ja", "correct": false, "because": "Breitere Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Können IT-Produkte ohne Rücksicht auf Recyclingmöglichkeiten ausgewählt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Recycling fördert Nachhaltigkeit"}, {"text": "Ja", "correct": false, "because": "Umweltschutzrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Umweltschutzaspekte bei der Auswahl von IT-Produkten immer kostenneutral?', 2, '[{"text": "Nein", "correct": true, "because": "Können höhere Anfangskosten verursachen"}, {"text": "Ja", "correct": false, "because": "Kosten variieren"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt ist bei Green IT am wichtigsten?', 3, '[{"text": "Energieeffizienz", "correct": true, "because": "Reduziert Umweltbelastung"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch"}, {"text": "Lieferzeit", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium fördert den Umweltschutz bei IT-Produkten?', 2, '[{"text": "Recyclingfähigkeit", "correct": true, "because": "Ermöglicht Wiederverwertung"}, {"text": "Gewicht", "correct": false, "because": "Physisch"}, {"text": "Design", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Zertifizierung ist ein Indikator für Green IT?', 2, '[{"text": "Energy Star", "correct": true, "because": "Zeigt Energieeffizienz"}, {"text": "ISO 9001", "correct": false, "because": "Qualitätsmanagement"}, {"text": "CE-Zeichen", "correct": false, "because": "Sicherheitsstandard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor reduziert den CO₂-Fußabdruck von IT-Produkten?', 3, '[{"text": "Geringer Stromverbrauch", "correct": true, "because": "Senkt Energiebedarf"}, {"text": "Hohe Anschaffungskosten", "correct": false, "because": "Wirtschaftlich"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel von Green IT?', 2, '[{"text": "Nachhaltigkeit", "correct": true, "because": "Umweltschutz fördern"}, {"text": "Kostensenkung", "correct": false, "because": "Indirekt"}, {"text": "Schnelle Installation", "correct": false, "because": "Nicht primär"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien fördern Umweltschutz bei IT-Produkten?', 4, '[{"text": "Energieeffizienz", "correct": true, "because": "Senkt Stromverbrauch"}, {"text": "Recyclingfähigkeit", "correct": true, "because": "Fördert Wiederverwertung"}, {"text": "Langlebigkeit", "correct": true, "because": "Reduziert Abfall"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte gehören zu Green IT?', 3, '[{"text": "Energieeffiziente Hardware", "correct": true, "because": "Reduziert Verbrauch"}, {"text": "Optimierte Software", "correct": true, "because": "Senkt Ressourcennutzung"}, {"text": "Nachhaltige Entsorgung", "correct": true, "because": "Fördert Recycling"}, {"text": "Hohe Anschaffungskosten", "correct": false, "because": "Wirtschaftlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Green IT bei IT-Produkten?', 3, '[{"text": "Geringerer Energieverbrauch", "correct": true, "because": "Umweltfreundlich"}, {"text": "Reduzierter CO₂-Ausstoß", "correct": true, "because": "Klimaschutz"}, {"text": "Imageverbesserung", "correct": true, "because": "Nachhaltigkeit positiv"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei mangelndem Umweltschutz von IT-Produkten auftreten?', 4, '[{"text": "Hoher Energieverbrauch", "correct": true, "because": "Belastet Umwelt"}, {"text": "Schwierige Entsorgung", "correct": true, "because": "Erhöht Abfall"}, {"text": "Rechtliche Verstöße", "correct": true, "because": "Umweltauflagen"}, {"text": "Geringe Leistung", "correct": false, "because": "Funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Zertifizierungen unterstützen Green IT?', 3, '[{"text": "Energy Star", "correct": true, "because": "Energieeffizienz"}, {"text": "EPEAT", "correct": true, "because": "Umweltfreundlichkeit"}, {"text": "TCO Certified", "correct": true, "because": "Nachhaltigkeit"}, {"text": "ISO 9001", "correct": false, "because": "Qualitätsmanagement"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Energieeffizienz fördert Green IT. b) Umweltschutz ist bei IT-Produkten immer vorgeschrieben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Effizienz ja, Vorschrift nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Recyclingfähigkeit unterstützt den Umweltschutz. b) Green IT beschränkt sich auf Hardware.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Recycling ja, Green IT umfassender"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Energy Star ist eine Green-IT-Zertifizierung. b) Umweltschutz erhöht immer die Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Energy Star ja, Kosten variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Green IT reduziert den CO₂-Ausstoß. b) Recyclingmöglichkeiten sind bei IT-Produkten unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "CO₂ ja, Recycling wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Langlebigkeit von IT-Produkten unterstützt den Umweltschutz. b) Green IT hat keinen Einfluss auf die Nachhaltigkeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Langlebigkeit ja, Green IT fördert Nachhaltigkeit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

